-- OCG-W rev2 (Codex W1-W7 review 718ba893/576d5575 at de5f6d9). Each trigger is one line because the local harness splits on a semicolon followed by a newline.
-- (1) Evidence revision pinning: an item and an experience entry record the source message version they were proposed against; an outcome records its evidence version.
-- (2) Instants are stored as UTC 'YYYY-MM-DDTHH:MM:SS.sssZ' so text order is time order. Existing rows are normalized once here.
-- (3) A rejected promoted item no longer blocks a retry promotion of the same source.
-- (4) An inverted validity window (valid_until <= valid_from) is refused in the database too.
ALTER TABLE memory_items ADD COLUMN source_version INTEGER;
ALTER TABLE experience_entries ADD COLUMN source_version INTEGER;
ALTER TABLE experience_entries ADD COLUMN outcome_message_version INTEGER;
DROP TRIGGER memory_items_frozen;
UPDATE memory_items SET valid_from=COALESCE(strftime('%Y-%m-%dT%H:%M:%fZ', valid_from), valid_from), valid_until=CASE WHEN valid_until IS NULL THEN NULL ELSE COALESCE(strftime('%Y-%m-%dT%H:%M:%fZ', valid_until), valid_until) END, source_version=COALESCE((SELECT max(h.version) FROM message_history h WHERE h.message_id=memory_items.source_message_id AND h.created_at<=memory_items.created_at), 1);
UPDATE experience_entries SET source_version=COALESCE((SELECT max(h.version) FROM message_history h WHERE h.message_id=experience_entries.source_message_id AND h.created_at<=experience_entries.created_at), 1), outcome_message_version=CASE WHEN outcome_message_id IS NULL THEN NULL ELSE COALESCE((SELECT max(h.version) FROM message_history h WHERE h.message_id=experience_entries.outcome_message_id AND h.created_at<=COALESCE(experience_entries.observed_at, experience_entries.created_at)), 1) END;
CREATE TRIGGER memory_items_frozen BEFORE UPDATE ON memory_items WHEN NEW.id IS NOT OLD.id OR NEW.room_id IS NOT OLD.room_id OR NEW.kind IS NOT OLD.kind OR NEW.tier IS NOT OLD.tier OR NEW.title IS NOT OLD.title OR NEW.body IS NOT OLD.body OR NEW.source_message_id IS NOT OLD.source_message_id OR NEW.source_version IS NOT OLD.source_version OR NEW.proposed_by IS NOT OLD.proposed_by OR NEW.valid_from IS NOT OLD.valid_from OR NEW.created_at IS NOT OLD.created_at OR (OLD.valid_until IS NOT NULL AND NEW.valid_until IS NOT OLD.valid_until) BEGIN SELECT RAISE(ABORT,'memory item content is immutable; propose a new item and supersede'); END;
CREATE TRIGGER memory_items_window BEFORE UPDATE OF valid_until ON memory_items WHEN NEW.valid_until IS NOT NULL AND NEW.valid_until<=NEW.valid_from BEGIN SELECT RAISE(ABORT,'validity window is inverted'); END;
CREATE TRIGGER memory_items_insert_guard BEFORE INSERT ON memory_items WHEN (NEW.valid_until IS NOT NULL AND NEW.valid_until<=NEW.valid_from) OR NEW.valid_from IS NOT strftime('%Y-%m-%dT%H:%M:%fZ', NEW.valid_from) OR (NEW.valid_until IS NOT NULL AND NEW.valid_until IS NOT strftime('%Y-%m-%dT%H:%M:%fZ', NEW.valid_until)) OR NOT EXISTS (SELECT 1 FROM message_history h WHERE h.message_id=NEW.source_message_id AND h.version=NEW.source_version) BEGIN SELECT RAISE(ABORT,'memory item needs a UTC validity window in order and a pinned source version'); END;
CREATE TRIGGER memory_edges_promotion_version BEFORE INSERT ON memory_edges WHEN NEW.type='PROMOTED_FROM' AND NOT EXISTS (SELECT 1 FROM memory_items n JOIN memory_items o ON o.id=NEW.dst_id WHERE n.id=NEW.src_id AND n.source_version IS o.source_version) BEGIN SELECT RAISE(ABORT,'promotion must be one tier up from an approved item and keep its kind, room, validity window and source'); END;
CREATE TRIGGER memory_edges_supersede_window BEFORE INSERT ON memory_edges WHEN NEW.type='SUPERSEDED_BY' AND NOT EXISTS (SELECT 1 FROM memory_items o JOIN memory_items n ON n.id=NEW.dst_id WHERE o.id=NEW.src_id AND n.room_id=o.room_id AND n.valid_from>o.valid_from) BEGIN SELECT RAISE(ABORT,'supersede must stay in one room and start after the old item'); END;
DROP TRIGGER memory_edges_promotion_single;
CREATE TRIGGER memory_edges_promotion_single BEFORE INSERT ON memory_edges WHEN NEW.type='PROMOTED_FROM' AND EXISTS (SELECT 1 FROM memory_edges e WHERE e.type='PROMOTED_FROM' AND (e.src_id=NEW.src_id OR e.dst_id=NEW.dst_id) AND e.review_state IN ('pending','approved') AND NOT EXISTS (SELECT 1 FROM memory_items x WHERE x.id=e.src_id AND x.review_state='rejected')) BEGIN SELECT RAISE(ABORT,'item already has an open promotion'); END;
CREATE TRIGGER experience_versions_frozen BEFORE UPDATE ON experience_entries WHEN NEW.source_version IS NOT OLD.source_version OR (OLD.outcome_message_version IS NOT NULL AND NEW.outcome_message_version IS NOT OLD.outcome_message_version) BEGIN SELECT RAISE(ABORT,'experience evidence versions are immutable'); END;
CREATE TRIGGER experience_source_version BEFORE INSERT ON experience_entries WHEN NOT EXISTS (SELECT 1 FROM message_history h WHERE h.message_id=NEW.source_message_id AND h.version=NEW.source_version) BEGIN SELECT RAISE(ABORT,'experience needs a pinned source version'); END;
CREATE TRIGGER experience_outcome_version BEFORE UPDATE OF outcome_message_id, outcome_message_version ON experience_entries WHEN NEW.outcome_message_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM message_history h WHERE h.message_id=NEW.outcome_message_id AND h.version=NEW.outcome_message_version) BEGIN SELECT RAISE(ABORT,'outcome needs a pinned evidence version'); END;
